/**
 * report.js - Generate the artefacts an OEM compliance file actually needs:
 * a compliance report, a NOTICE file, an obligation checklist and a supplier inquiry draft.
 */

import { OBLIGATIONS, TIERS } from './license-db.js';

const sevOrder = { CRITICAL: 0, HIGH: 1, MEDIUM: 2, LOW: 3 };

/** obligation id -> components that trigger it */
export function groupByObligation(analysis) {
  const map = new Map();
  for (const c of analysis.components) {
    for (const o of c.obligations || []) {
      if (!map.has(o)) map.set(o, []);
      map.get(o).push(c);
    }
  }
  return [...map.entries()]
    .map(([id, comps]) => ({ id, text: OBLIGATIONS[id] || id, components: comps }))
    .sort((a, b) => b.components.length - a.components.length);
}

export function renderComplianceReport(analysis, opts = {}) {
  const L = [];
  const m = analysis.meta;
  const now = opts.date || new Date().toISOString().slice(0, 10);

  L.push(`# OSS Compliance Report`);
  L.push(``);
  L.push(`| Field | Value |`);
  L.push(`|---|---|`);
  L.push(`| Document | ${m.name || '-'} |`);
  L.push(`| SPDX version | ${m.spdxVersion || '-'} |`);
  L.push(`| Generated | ${now} |`);
  L.push(`| Supplier | ${opts.supplier || (m.creators || []).join(', ') || '-'} |`);
  L.push(`| ECU / programme | ${opts.ecu || '-'} |`);
  L.push(`| Milestone | ${opts.milestone || '-'} |`);
  L.push(`| Prepared by | ${opts.preparedBy || '-'} |`);
  L.push(``);
  L.push(`> Engineering triage generated by OSS Compliance Smart Analyzer. Not legal advice.`);
  L.push(`> Every CRITICAL and HIGH finding requires confirmation by legal counsel.`);
  L.push(``);

  L.push(`## 1. Verdict`);
  L.push(``);
  L.push(`**Risk score ${analysis.score.value}/100 (band: ${analysis.score.band})**`);
  L.push(``);
  L.push(`| Metric | Value |`);
  L.push(`|---|---|`);
  L.push(`| Components | ${analysis.components.length} |`);
  L.push(`| Critical (strong / network copyleft) | ${analysis.tierCounts.CRITICAL || 0} |`);
  L.push(`| High (weak / file copyleft) | ${analysis.tierCounts.HIGH || 0} |`);
  L.push(`| Unresolved licenses | ${analysis.components.filter(c => !c.declaration.resolved).length} |`);
  L.push(`| Findings (critical / high / medium) | ${analysis.counts.CRITICAL} / ${analysis.counts.HIGH} / ${analysis.counts.MEDIUM} |`);
  L.push(`| SBOM quality (NTIA + audit) | ${analysis.quality.score}% (${analysis.quality.passed}/${analysis.quality.total}) |`);
  L.push(``);

  L.push(`**Release recommendation:** ${
    analysis.counts.CRITICAL > 0 ? 'DO NOT SIGN OFF - critical findings open.'
    : analysis.components.some(c => !c.declaration.resolved) ? 'CONDITIONAL - unresolved licenses must be closed first.'
    : analysis.counts.HIGH > 0 ? 'CONDITIONAL - high findings need documented waivers.'
    : 'NO BLOCKING FINDINGS - proceed with the standard review.'
  }`);
  L.push(``);

  L.push(`## 2. Findings`);
  L.push(``);
  const bySev = ['CRITICAL', 'HIGH', 'MEDIUM', 'LOW'];
  for (const sev of bySev) {
    const fs = analysis.findings.filter(f => f.severity === sev);
    if (!fs.length) continue;
    L.push(`### ${sev} (${fs.length})`);
    L.push(``);
    for (const f of fs) {
      L.push(`- **${f.title}** \`${f.rule}\``);
      L.push(`  - Component: ${f.component}`);
      L.push(`  - Evidence: ${f.detail}`);
      L.push(`  - Obligation: ${f.obligation}`);
      L.push(`  - Action: ${f.action}`);
    }
    L.push(``);
  }

  L.push(`## 3. Obligation checklist`);
  L.push(``);
  for (const g of groupByObligation(analysis)) {
    L.push(`- [ ] **${g.text}** - ${g.components.length} component(s)`);
    L.push(`  - ${g.components.map(c => c.name).slice(0, 20).join(', ')}${g.components.length > 20 ? ', ...' : ''}`);
  }
  L.push(``);

  const sourceOffer = analysis.components.filter(c =>
    (c.obligations || []).some(o => ['source-full', 'source-modified', 'network-source'].includes(o)));
  L.push(`## 4. Source-offer package`);
  L.push(``);
  L.push(sourceOffer.length
    ? sourceOffer.map(c => `- ${c.name} ${c.version || ''} - ${c.effectiveLicense}`).join('\n')
    : '- none');
  L.push(``);

  const relink = analysis.components.filter(c => (c.obligations || []).includes('relinking'));
  L.push(`## 5. Relinking mechanism required`);
  L.push(``);
  L.push(relink.length
    ? relink.map(c => `- ${c.name} ${c.version || ''} (${c.effectiveLicense})`).join('\n')
    : '- none');
  L.push(``);

  const unresolved = analysis.components.filter(c => !c.declaration.resolved);
  L.push(`## 6. Unresolved licenses - supplier action required`);
  L.push(``);
  L.push(unresolved.length
    ? unresolved.map(c => `- ${c.name} ${c.version || ''} - declared "${c.effectiveLicense || 'empty'}" (${c.licenseSource}, supplier: ${c.supplier || '-'})`).join('\n')
    : '- none');
  L.push(``);

  L.push(`## 7. SBOM quality`);
  L.push(``);
  L.push(`| Check | Status | Detail |`);
  L.push(`|---|---|---|`);
  for (const c of analysis.quality.checks) {
    L.push(`| ${c.id} ${c.label} | ${c.ok ? 'OK' : 'MISSING'} | ${c.detail} |`);
  }
  L.push(``);

  return L.join('\n');
}

export function renderNoticeFile(analysis) {
  const withNotice = analysis.components
    .filter(c => (c.obligations || []).includes('notice'))
    .sort((a, b) => (a.name || '').localeCompare(b.name || ''));

  const L = [];
  L.push(`NOTICES AND ATTRIBUTIONS`);
  L.push(`========================`);
  L.push(``);
  L.push(`Product: ${analysis.meta.name || '-'}`);
  L.push(`Generated: ${new Date().toISOString().slice(0, 10)}`);
  L.push(``);
  L.push(`This product contains open source software. The following components are`);
  L.push(`subject to attribution requirements.`);
  L.push(``);

  for (const c of withNotice) {
    L.push(`----------------------------------------------------------------`);
    L.push(`Component:   ${c.name}${c.version ? ' ' + c.version : ''}`);
    L.push(`License:     ${c.effectiveLicense || 'NOASSERTION'}`);
    if (c.purl) L.push(`Package URL: ${c.purl}`);
    if (c.downloadLocation && !/NOASSERTION/i.test(c.downloadLocation)) {
      L.push(`Source:      ${c.downloadLocation}`);
    }
    if (c.copyright && !/NOASSERTION/i.test(c.copyright)) {
      L.push(`Copyright:   ${c.copyright.replace(/\s+/g, ' ').slice(0, 400)}`);
    }
    L.push(``);
  }
  return L.join('\n');
}

export function renderSupplierInquiry(analysis, opts = {}) {
  const blockers = analysis.findings
    .filter(f => f.severity === 'CRITICAL' || f.severity === 'HIGH')
    .filter(f => ['LIC-003', 'LIC-004', 'LIC-006', 'LIC-009', 'LIC-005'].includes(f.rule));

  const L = [];
  L.push(`Subject: OSS compliance findings - ${analysis.meta.name || 'SBOM'} - action required`);
  L.push(``);
  L.push(`Dear ${opts.supplier || 'supplier'},`);
  L.push(``);
  L.push(`We reviewed the SBOM delivered for ${opts.ecu || 'the ECU'} / milestone ${opts.milestone || '-'}.`);
  L.push(`Score: ${analysis.score.value}/100 (${analysis.score.band}); SBOM quality ${analysis.quality.score}%.`);
  L.push(`The following items block release sign-off. Please respond per item.`);
  L.push(``);

  if (!blockers.length) {
    L.push(`No critical or high findings. Please confirm the SBOM is complete and current.`);
    return L.join('\n');
  }

  blockers.forEach((f, i) => {
    L.push(`${i + 1}. [${f.severity}] ${f.title} (\`${f.rule}\`)`);
    L.push(`   Finding:   ${f.detail}`);
    L.push(`   Question:  ${f.action}`);
    L.push(`   Response:  ______________________________________________`);
    L.push(``);
  });

  const incomplete = analysis.quality.checks.filter(c => !c.ok);
  if (incomplete.length) {
    L.push(`Additionally, the SBOM is incomplete and must be re-delivered:`);
    for (const c of incomplete) L.push(`- ${c.id} ${c.label}: ${c.detail}`);
    L.push(``);
  }
  L.push(`Please return the updated SBOM (SPDX 2.3 JSON) and this response by ${opts.dueDate || '[date]'}.`);
  L.push(``);
  L.push(`Kind regards,`);
  L.push(opts.preparedBy || '[name]');
  return L.join('\n');
}

export function renderComponentsCsv(analysis) {
  const head = ['component', 'version', 'purl', 'supplier', 'license', 'licenseSource', 'tier',
    'copyleft', 'inheritedFrom', 'linkage', 'obligations'];
  const rows = analysis.components.map(c => [
    c.name, c.version, c.purl || '', c.supplier, c.effectiveLicense, c.licenseSource,
    c.tier, c.copyleft,
    c.taintedBy.map(t => t.name).join(' | '),
    c.taintedBy.map(t => t.linkKind).join(' | '),
    (c.obligations || []).join(' ')
  ]);
  return [head, ...rows]
    .map(r => r.map(v => `"${String(v ?? '').replace(/"/g, '""')}"`).join(','))
    .join('\n');
}

export function renderDiffReport(d, opts = {}) {
  const v = diffVerdictText(d);
  const L = [];
  L.push(`# SBOM Milestone Diff`);
  L.push(``);
  L.push(`| | Baseline | Current |`);
  L.push(`|---|---|---|`);
  L.push(`| Document | ${d.baseline.name} | ${d.current.name} |`);
  L.push(`| Created | ${d.baseline.created || '-'} | ${d.current.created || '-'} |`);
  L.push(`| Risk score | ${d.baseline.score.value} (${d.baseline.score.band}) | ${d.current.score.value} (${d.current.score.band}) |`);
  L.push(``);
  L.push(`**Verdict: ${v}**  Risk delta: ${d.riskDelta >= 0 ? '+' : ''}${d.riskDelta}, SBOM quality delta: ${d.qualityDelta >= 0 ? '+' : ''}${d.qualityDelta}`);
  L.push(``);

  const section = (title, rows) => {
    L.push(`## ${title}`);
    L.push(``);
    L.push(rows.length ? rows.map(r => '- ' + r).join('\n') : '- none');
    L.push(``);
  };

  section(`New components (${d.counts.added})`,
    d.added.map(c => `${c.name} ${c.version || ''} - ${c.effectiveLicense || 'NOASSERTION'} - ${TIERS[c.tier].label}`));
  section(`Removed components (${d.counts.removed})`,
    d.removed.map(c => `${c.name} ${c.version || ''} - ${c.effectiveLicense || 'NOASSERTION'}`));
  section(`License changes (${d.counts.licenseChanged})`,
    d.licenseChanged.map(l => `${l.component.name}: "${l.from}" (${l.fromTier}) -> "${l.to}" (${l.toTier})${l.escalated ? ' **ESCALATED**' : ''}`));
  section(`Version changes (${d.counts.versionChanged})`,
    d.versionChanged.map(v2 => `${v2.component.name}: ${v2.from || '-'} -> ${v2.to || '-'}`));
  section(`New copyleft introduced (${d.newCopyleft.length})`,
    d.newCopyleft.map(c => `${c.name} - ${c.effectiveLicense} - ${c.tier}`));
  section(`Copyleft removed (${d.goneCopyleft.length})`,
    d.goneCopyleft.map(c => `${c.name} - ${c.effectiveLicense}`));
  section(`Newly resolved licenses (${d.resolvedNow.length})`,
    d.resolvedNow.map(c => `${c.name} -> ${c.effectiveLicense}`));
  section(`Regressions to unresolved (${d.regressed.length})`,
    d.regressed.map(c => `${c.name} -> ${c.effectiveLicense || 'NOASSERTION'}`));
  section(`New findings (${d.counts.newFindings}, ${d.counts.newCritical} critical / ${d.counts.newHigh} high)`,
    d.newFindings.map(f => `[${f.severity}] ${f.rule} ${f.title}`));
  section(`Closed findings (${d.counts.fixedFindings})`,
    d.fixedFindings.map(f => `[${f.severity}] ${f.rule} ${f.title}`));
  return L.join('\n');
}

function diffVerdictText(d) {
  if (d.counts.newCritical > 0) return `${d.counts.newCritical} NEW CRITICAL findings - escalation required`;
  if (d.counts.newHigh > 0) return `${d.counts.newHigh} new high findings - review required`;
  if (d.counts.newFindings > 0) return `${d.counts.newFindings} new findings - check`;
  if (d.counts.licenseChanged > 0) return `${d.counts.licenseChanged} license changes - check`;
  return 'no new compliance findings';
}
